<?php class AdminController extends Controller{function index(){ $m=$this->model('Menu');$b=$this->model('Booking');$menu=$m->get();$bookings=$b->get(); if(isset($_POST['add'])){$img='default-food.jpg'; if(!empty($_FILES['gambar']['name'])){$img=time().'_'.basename($_FILES['gambar']['name']); move_uploaded_file($_FILES['gambar']['tmp_name'],'assets/images/'.$img);} $menu[]=['nama'=>$_POST['nama'],'harga'=>$_POST['harga'],'gambar'=>$img]; $m->save($menu); header('Location:index.php?page=admin'); exit;} if(isset($_POST['update'])){$id=$_POST['id']; $img=$menu[$id]['gambar']; if(!empty($_FILES['gambar']['name'])){$img=time().'_'.basename($_FILES['gambar']['name']); move_uploaded_file($_FILES['gambar']['tmp_name'],'assets/images/'.$img);} $menu[$id]=['nama'=>$_POST['nama'],'harga'=>$_POST['harga'],'gambar'=>$img]; $m->save($menu); header('Location:index.php?page=admin'); exit;} if(isset($_GET['delete'])){unset($menu[$_GET['delete']]);$m->save(array_values($menu)); header('Location:index.php?page=admin'); exit;} if(isset($_POST['status'])){$bookings[$_POST['id']]['status']=$_POST['booking_status']; $b->save($bookings); header('Location:index.php?page=admin'); exit;} if(isset($_GET['delbook'])){unset($bookings[$_GET['delbook']]); $b->save(array_values($bookings)); header('Location:index.php?page=admin'); exit;} include 'views/admin/index.php';}} ?>